class ClassBaseDevice{constructor(_opts){if(this._Bus=_opts.bus,this._Pins=_opts.pins,this._Address=_opts.address,this._Id=_opts.id,this._Article=_opts.article,this._Name=_opts.name,this._Type=_opts.subChannels?"hybrid":_opts.type,this._ChannelNames=Array.isArray(_opts.channelNames)?_opts.channelNames.reduce((acc,item,index)=>(acc[item]=index,acc),{}):this._ChannelNames,this.CheckProps(),"hybrid"===this._Type.toLowerCase())try{this._SubChannels=_opts.subChannels.map(_subChId=>{let dev_id=_subChId.split("-")[0],chNum=_subChId.split("-")[1];return H.DeviceManager.Service.CreateDevice(dev_id)[chNum]})}catch(e){throw H.Logger.Service.Log({service:this._Id,level:"E",msg:"Error while parsing subChannels option"}),e}}CheckProps(){const isStringNonEmpty=p=>"string"==typeof p&&p.length>0,isChNamesObj=p=>"object"==typeof p&&Object.keys(p).every(i=>isStringNonEmpty(i)&&Object.values(p).every(i=>"number"==typeof i));if(!isStringNonEmpty(this._Id))throw new Error("Invalid _Id");if(!isStringNonEmpty(this._Article))throw new Error("Invalid _Article");if(!isStringNonEmpty(this._Name))throw new Error("Invalid _Name");if(!isChNamesObj(this._ChannelNames))throw new Error("Invalid _ChannelNames");if(this._Bus instanceof I2C&&"number"!=typeof+this._Address)throw new Error("Address of i2c device is not provided")}GetInfo(){return{bus:this._Bus,pins:this._Pins,id:this._Id,article:this._Article,name:this._Name,type:this._Type,channelNames:this._ChannelNames}}}class ClassDevice extends ClassBaseDevice{constructor(_opts){ClassBaseDevice.call(this,_opts)}get ID(){return this._Id}get CountChannels(){return this._Channels.filter(o=>"object"==typeof o).length}GetChannel(_num){return this._Channels[_num]}GetInfo(_chNum,_opts){}Init(_opts){}Configure(_chNum,_opts){}Reset(_chNum){}Read(_reg){}Write(_reg,_val){}}exports=ClassDevice;